function certificates(){const careers=['All',...new Set(data.certifications.map(c=>c.career))];return heading('13 PATHWAYS · YOUR PACE','Choose your quest.','Each pathway reuses shared foundations, adds focused lessons, links the current issuer blueprint and keeps its unfinished coverage visible.')+`<div class="filters">${careers.map(c=>`<button data-filter="${esc(c)}" aria-pressed="${filter===c}" class="${filter===c?'selected':''}">${esc(c)}</button>`).join('')}</div><div class="grid">${data.certifications.filter(c=>filter==='All'||c.career===filter).map(certCard).join('')}</div><div class="notice">Google IT Support is a course-based professional certificate. The other paths lead to separate vendor exams. Athena awards neither, and progress here does not predict an exam pass.</div>`;}
function trackView(id){const c=track(id);if(!c)return notFound();return heading(c.career,c.name,c.version)+`<div class="actions"><button class="button" data-select="${c.id}">${state.selectedTrack===c.id?'Current learning quest ✓':'Make this my quest'}</button>${button('Official blueprint ↗',c.sources[0].url,true)}</div><div class="notice"><strong>Coverage:</strong> ${esc(c.coverage)}<br><strong>Source status:</strong> ${esc(c.verification)}</div><div class="split"><section class="panel"><h2>Your introductory route</h2>${c.lessonIds.map((id,i)=>{const l=lesson(id);return `<div class="lesson-row"><span class="num">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${state.read[id]?'Read · ':''}${state.checks[id]?'Check passed':'Concept check available'}</p></div><button class="quiet" data-lesson="${id}">Open →</button></div>`;}).join('')}</section><aside class="panel"><h2>Before you book</h2><ul class="source-list">${c.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul><h3>Price check</h3><p class="meta">${esc(c.price.status)}</p><h3>Official sources</h3><ul class="source-list">${c.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.purpose)} ↗</a></li>`).join('')}</ul><small class="meta">Reviewed ${data.reviewedAt}. Recheck the exact version, language and price before booking.</small></aside></div><div class="section-head"><h2>Domain roadmap</h2><span class="pill warning">Full subobjective coverage is open</span></div><div class="panel">${c.domainCoverage.map((d,i)=>`<div class="domain"><h3>${i+1}. ${esc(d.title)} ${c.weightsPercent?`<span class="pill">${esc(c.weightsPercent[i])}%</span>`:''}</h3><p>${esc(d.reason)}</p></div>`).join('')}</div><div class="section-head"><h2>Capstone: ${esc(c.lab.title)}</h2></div><div class="split"><div class="panel"><h3>Mission plan</h3><ol class="source-list">${c.lab.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div><div class="panel"><h3>What counts as evidence?</h3><ul class="source-list">${c.lab.acceptance.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><span class="pill warning">Guided plan, not an executed lab</span></div></div>`;}
